// src/app/stories/[slug]/page.tsx
import { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { getStory, getAllStorySlugs } from '@/lib/stories';
import { getAuthor } from '@/lib/authors';
import Breadcrumbs from '@/components/Breadcrumbs';
import StoryFeatured from '@/components/Stories/StoryFeatured';
import AuthorCard from '@/components/Blog/AuthorCard';
import StoryAbout from '@/components/Stories/StoryAbout';
import StoryFinalNewsletter from '@/components/Stories/StoryFinalNewsletter';
import StoryReadMore from '@/components/Stories/StoryReadMore';
import SocialFollowCTA from '@/components/ui/SocialFollowCTA';
import { remark } from 'remark';
import remarkGfm from 'remark-gfm';
import remarkHtml from 'remark-html';
import { StoryBodyImage } from '@/types/stories';

export const dynamic = 'force-static';
export const revalidate = false;

// Splits compiled HTML into segments at <h2> boundaries so bodyImages can be
// placed after a specific heading index, mirroring NailFeedTemplate's
// splitContentIntoThirds pattern but keyed off explicit afterHeading values
// instead of fixed thirds.
function splitContentAtHeadings(html: string): string[] {
  const blocks = html.split(/(?=<h2[\s>])/);
  return blocks;
}

// Renders a credit line — used for both hero and body image credits so the
// styling stays consistent across the page.
function ImageCredit({
  socialLink,
  displayText,
  align = 'right',
}: {
  socialLink?: string;
  displayText?: string;
  align?: 'right' | 'left';
}) {
  if (!displayText) return null;
  return (
    <p
      className={`font-ui text-xs text-foreground/50 mt-2 ${
        align === 'right' ? 'text-right' : 'text-left'
      }`}
    >
      {socialLink ? (
        <a
          href={socialLink}
          target="_blank"
          rel="noopener noreferrer"
          className="hover:text-foreground underline"
        >
          {displayText}
        </a>
      ) : (
        displayText
      )}
    </p>
  );
}

function BodyImageBlock({ image, creditEnabled }: { image: StoryBodyImage; creditEnabled: boolean }) {
  return (
    <div className="w-full max-w-[560px] mx-auto my-8">
      {/*
        Native resolution, no forced aspect ratio, no cropping, no background
        box. The image renders at its own size, capped only by max-width /
        max-height so nothing overflows the layout.
      */}
      <img
        src={image.src}
        alt={image.alt}
        className="block w-auto h-auto max-w-full max-h-[700px] mx-auto"
      />
      {creditEnabled && (
        <ImageCredit socialLink={image.creditSocialLink} displayText={image.creditDisplayText} />
      )}
    </div>
  );
}

interface PageProps {
  params: Promise<{ slug: string }>;
}

export async function generateStaticParams() {
  const slugs = await getAllStorySlugs();
  return slugs.map((slug) => ({ slug }));
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { slug } = await params;
  const story = await getStory(slug);
  if (!story) return {};

  return {
    title: story.title,
    description: story.excerpt,
    alternates: { canonical: story.canonical || `https://mirelleinspo.com/stories/${slug}` },
    openGraph: {
      title: story.title,
      description: story.excerpt,
      url: `https://mirelleinspo.com/stories/${slug}`,
      siteName: 'Mirellé Inspo',
      type: 'article',
      publishedTime: story.date,
      modifiedTime: story.dateModified || story.date,
      authors: [story.author],
      images: [{ url: story.image, width: 1200, height: 675, alt: story.title }],
    },
    twitter: {
      card: 'summary_large_image',
      title: story.title,
      description: story.excerpt,
      images: [story.image],
    },
    robots: {
      index: true,
      follow: true,
      googleBot: { index: true, follow: true, 'max-video-preview': -1, 'max-image-preview': 'large', 'max-snippet': -1 },
    },
  };
}

export default async function StoryPage({ params }: PageProps) {
  const { slug } = await params;
  const story = await getStory(slug);
  if (!story) notFound();

  const author = getAuthor(story.author);

  const formattedDate = new Date(story.date).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });

  const processed = await remark().use(remarkGfm).use(remarkHtml).process(story.content);
  const contentHtml = processed.toString();
  const headingBlocks = splitContentAtHeadings(contentHtml);

  const bodyImages = story.bodyImages || [];
  const creditEnabled = story.creditBodyImages ?? true;

  return (
    <article className="min-h-screen bg-background">
      <div className="max-w-[1200px] mx-auto">
        <div className="max-w-[800px] px-6 pt-8">
          <Breadcrumbs
            items={[{ label: 'Stories', href: '/stories' }]}
            currentPage={story.title}
          />

          {story.category && (
            <p className="font-ui uppercase text-xs text-foreground/50 tracking-wider mt-6">
              {story.category}
            </p>
          )}

          <h1 className="font-heading text-4xl md:text-5xl leading-tight mt-3 mb-4">
            {story.title}
          </h1>

          <div className="flex items-center gap-2 font-ui text-sm text-foreground/60 mb-8">
            <span>BY {story.author.toUpperCase()}</span>
            <span>·</span>
            <time dateTime={story.date}>{formattedDate}</time>
          </div>
        </div>

        {/* Hero — shown at native resolution, capped to max-width/max-height so
            large images don't overflow the layout. No forced aspect ratio,
            no cropping, no background box. Left edge aligns with the title's
            left edge; hero can extend wider than the text column within the
            shared 1200px frame. Credit line renders underneath when
            imageCreditDisplayText is set. */}
        <div className="px-6 mb-8">
          <div className="inline-block max-w-full">
            <img
              src={story.image}
              alt={story.imageAlt || story.title}
              className="block w-auto h-auto max-w-full max-h-[900px]"
            />
            <ImageCredit
              socialLink={story.imageCreditSocialLink}
              displayText={story.imageCreditDisplayText}
            />
          </div>
        </div>

        <div className="max-w-[800px] px-6">
          <article className="prose prose-lg max-w-none font-body prose-headings:font-heading prose-a:text-foreground prose-a:underline">
            {headingBlocks.map((block, i) => {
              const isHalfway = headingBlocks.length > 1 && i === Math.floor(headingBlocks.length / 2);
              return (
                <div key={`block-${i}`}>
                  <div dangerouslySetInnerHTML={{ __html: block }} />
                  {bodyImages
                    .filter((img) => img.afterHeading === i)
                    .map((img, j) => (
                      <BodyImageBlock key={`bi-${i}-${j}`} image={img} creditEnabled={creditEnabled} />
                    ))}
                  {isHalfway && (
                    <div className="not-prose my-10">
                      <SocialFollowCTA platforms={['instagram', 'pinterest', 'twitter', 'facebook', 'youtube']} />
                    </div>
                  )}
                </div>
              );
            })}
          </article>
        </div>

        {story.featured && (
          <div className="mt-16">
            <StoryFeatured person={story.featured} />
          </div>
        )}

        {author && (
          <div className="max-w-[800px] px-6 mt-16">
            <AuthorCard author={author} />
          </div>
        )}
      </div>

      <div className="mt-16">
        <StoryAbout />
      </div>

      <StoryFinalNewsletter />

      <StoryReadMore currentSlug={slug} />
    </article>
  );
}

// src/types/stories.ts

export interface StoryBodyImage {
  src: string;
  alt: string;
  creditSocialLink?: string;
  creditDisplayText?: string;
  /** Position in content where this image renders — after this heading index (0-based h2 count), or 'end' */
  afterHeading: number;
}

export interface StoryFeaturedPerson {
  name: string;
  image: string;
  bio: string;
  social?: string;
}

export interface StoryMetadata {
  slug: string;
  title: string;
  excerpt: string;
  date: string;
  dateModified?: string;
  author: string;
  category: string;
  image: string; // hero image, shown at native aspect ratio, 1200x675 (16:9) recommended per Discover spec
  imageAlt?: string;
  imageCreditSocialLink?: string; // optional — link for the hero image credit line
  imageCreditDisplayText?: string; // optional — if omitted, no hero credit line renders
  creditBodyImages?: boolean; // if false, never render credit lines even if present in bodyImages
  bodyImages?: StoryBodyImage[]; // images placed within the article body, at fixed positions
  readTime?: number | string;
  wordCount?: number;
  canonical?: string;
  tags?: string[];
  featured?: StoryFeaturedPerson;
  topicalMap?: {
    position?: string;
    parentPillar?: string;
    relatedClusters?: string[];
    primaryKeyword?: string;
    searchIntent?: string;
    topicalBoundary?: string;
    hierarchyLevel?: number;
    secondaryKeywords?: string[];
    contentType?: string;
    semanticRelationships?: {
      technique?: string[];
      style?: string[];
      occasions?: string[];
      relatedTechniques?: string[];
    };
    contentMetrics?: {
      technicalComplexity?: string;
      timeToImplement?: string;
      requiredSkills?: string[];
      requiredTools?: string[];
    };
  };
  navigationContext?: {
    pillarPost?: {
      slug: string;
      title: string;
    };
  };
}

export interface Story extends StoryMetadata {
  content: string; // raw markdown string
}

export interface StoryCategory {
  name: string;
  slug: string;
  count: number;
}
